class BalancedBrackets:
    OPEN_BRACKET = "("
    CLOSE_BRACKET = ")"
    OPEN_CURLY_BRACKET = "{"
    CLOSE_CURLY_BRACKET = "}"
    OPEN_SQUARE_BRACKET = "["
    CLOSE_SQUARE_BRACKET = "]"

    def __init__(self, expr):
        self._stack = []
        self._left_brackets = [self.OPEN_BRACKET, self.OPEN_CURLY_BRACKET, self.OPEN_SQUARE_BRACKET]
        self._right_brackets = [self.CLOSE_BRACKET, self.CLOSE_CURLY_BRACKET, self.CLOSE_SQUARE_BRACKET]
        self._expr = expr

    @property
    def stack(self):
        return self._stack

    @property
    def left_brackets(self):
        return self._left_brackets

    @property
    def right_brackets(self):
        return self._right_brackets

    @property
    def expr(self):
        return self._expr

    @expr.setter
    def expr(self, value):
        self._expr = value

    def clear_expr(self):
        valid_brackets = set(self.left_brackets + self.right_brackets)
        self._expr = ''.join(c for c in self._expr if c in valid_brackets)

    def _is_matching_pair(self, left_brkt, right_brkt):
        if left_brkt == self.OPEN_BRACKET:
            return right_brkt == self.CLOSE_BRACKET
        if left_brkt == self.OPEN_CURLY_BRACKET:
            return right_brkt == self.CLOSE_CURLY_BRACKET
        if left_brkt == self.OPEN_SQUARE_BRACKET:
            return right_brkt == self.CLOSE_SQUARE_BRACKET
        return False

    def check_balanced_brackets(self):
        self.clear_expr()
        self._stack.clear()
        for brkt in self.expr:
            if brkt in self.left_brackets:
                self._stack.append(brkt)
            else:
                if not self._stack:
                    return False
                current_brkt = self._stack.pop()
                if not self._is_matching_pair(current_brkt, brkt):
                    return False
        return len(self._stack) == 0
